/* PVFINDER v1.1 — Join al servidor específico reportado */
.table-head,.feed-row{grid-template-columns:minmax(175px,1.5fr) minmax(120px,1fr) minmax(110px,.85fr) minmax(75px,.6fr) minmax(75px,.65fr) minmax(72px,.55fr)}
.join-cell{display:flex;justify-content:flex-end;align-items:center;min-width:0}
.join-button{display:inline-flex;align-items:center;justify-content:center;white-space:nowrap;min-width:67px;min-height:34px;padding:7px 10px;border:1px solid #63b7a0;border-radius:9px;color:#a8ffe1;background:linear-gradient(130deg,#153b32,#0e2b30);text-decoration:none;font-size:11px;font-weight:850;letter-spacing:.06em;box-shadow:0 0 14px #2bcf9850;cursor:pointer}
.join-button:hover{filter:brightness(1.15);color:white}
.join-button.join-disabled{border-color:#3a4559;background:#182130;color:#6d7d97;box-shadow:none;cursor:not-allowed;opacity:.85}
@media(max-width:1100px){
 .table-head,.feed-row{grid-template-columns:minmax(135px,1.5fr) minmax(100px,1fr) minmax(90px,.8fr) minmax(60px,.55fr) minmax(70px,.65fr)}
 .table-head span:nth-child(5),.feed-row>div:nth-child(5){display:none}
 .table-head span:nth-child(6),.feed-row>div:nth-child(6){display:flex}
}
@media(max-width:750px){
 .table-head,.feed-row{grid-template-columns:minmax(130px,1.7fr) minmax(85px,.85fr) minmax(65px,.65fr);gap:7px}
 .table-head span:nth-child(2),.feed-row>div:nth-child(2),.table-head span:nth-child(4),.feed-row>div:nth-child(4),.table-head span:nth-child(5),.feed-row>div:nth-child(5){display:none}
 .table-head span:nth-child(6),.feed-row>div:nth-child(6){display:flex}
 .join-button{min-width:64px;padding:7px 8px;font-size:10px}
}

/* PVFinder: filtro de ingresos mínimos, adaptable a móvil */
.filters select#minIncomeFilter{border-color:#6555a6;background:linear-gradient(120deg,#211d3e,#151e30);color:#d9d0ff;font-weight:750}
.filters select#minIncomeFilter:focus{border-color:#ad8fff;box-shadow:0 0 0 3px #8764e52a}
@media(max-width:750px){.filters{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.filters select{width:100%;max-width:none;min-width:0}.filters #minIncomeFilter{grid-column:1 / -1}}

/* PVFinder — filtro único de ingresos en lugar de bioma/servidor. */
.panel-bar .filters{display:flex;align-items:center;justify-content:flex-end;gap:10px;flex-wrap:wrap}
.filters .income-filter-label{font-size:10px;font-weight:800;letter-spacing:.08em;color:#b7a5ff}
.filters select#minIncomeFilter{min-width:190px;max-width:260px;width:auto;height:38px;padding:0 11px;background:linear-gradient(120deg,#272047,#151e30);border:1px solid #7960c7;color:#f2edff;box-shadow:0 0 10px #715cbb19}
@media(max-width:750px){
 .panel-bar .filters{display:flex;flex-direction:column;align-items:stretch;gap:7px;width:100%}
 .filters .income-filter-label{font-size:10px}
 .filters select#minIncomeFilter{width:100%;max-width:none;min-width:0;grid-column:auto}
}

/* Vista de cliente: Live Feed solamente. Estadísticas y herramientas, solo admin. */
body.viewer-mode .admin-only{display:none!important}
body.viewer-mode .main-content{max-width:1180px;margin-inline:auto;width:100%}
body.viewer-mode .section-top{margin-bottom:20px}

.site-announcement{display:block;margin:15px auto 0;width:calc(100% - 70px);padding:14px 18px;border:1px solid var(--purple);border-radius:12px;text-align:center;background:#211c3d;color:var(--text);font-weight:750;font-size:13px}.site-announcement[hidden]{display:none!important}
@media(max-width:700px){.site-announcement{width:calc(100% - 28px)}}

:root{--radar-accent:#c2a4ff;--radar-gold:#ffd879}
.radar-cover{display:block;width:100%;height:auto;border:1px solid #57488a;border-radius:14px;margin-bottom:1rem}
.radar-old-orbit{display:none}
.radar-toolbar{display:flex;align-items:end;gap:12px;flex-wrap:wrap;padding:16px;border-bottom:1px solid #372e56;background:#1b1631}
.radar-toolbar [role=group]{display:flex;gap:6px}
.radar-toolbar label{display:grid;gap:4px;font-size:12px;color:#c0b6d7}
.radar-toolbar button,.radar-toolbar input,.radar-toolbar select{border:1px solid #665187;background:#201832;color:#fff;border-radius:8px;padding:8px 11px;font:inherit}
.radar-toolbar button[aria-pressed=true]{background:var(--radar-accent);color:#1c1032;font-weight:800}
.radar-toolbar[hidden],#resultsPanel .table-head[hidden]{display:none}
#feedRows.radar-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(255px,100%),1fr));align-items:start;gap:14px;padding:14px}
.radar-card{min-width:0;padding:13px;border-radius:15px;border:1px solid #574183;background:linear-gradient(140deg,#251c43,#16152b)}
.radar-title{display:grid;grid-template-columns:64px minmax(0,1fr);gap:12px;align-items:center}
.radar-title h2{margin:3px 0 5px;font-size:17px;line-height:1.2;overflow-wrap:anywhere}
.radar-title small,.radar-count,.radar-report small,.radar-old{display:block;color:#beb3d1;font-size:12px}
.radar-thumb{height:64px;display:grid;place-items:center;background:#33254d;border-radius:12px;color:var(--radar-gold);font-size:30px}
.radar-thumb img{width:56px;height:56px;object-fit:contain}
.radar-count{margin:12px 0 6px}
.radar-report{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:7px 0;border-top:1px solid #493960}
.radar-report strong{color:var(--radar-gold)}
.radar-report .join-button{min-width:0}
.radar-card summary{color:var(--radar-accent);cursor:pointer;font-size:13px;padding:7px 0}

#gate.access-entry:not(.hidden) {
 display:grid;
 grid-template-columns:minmax(0,1fr);
 place-items:center;
 min-height:calc(100svh - 95px);
 width:100%;
 max-width:none;
 padding:clamp(18px,4vw,48px) 16px;
 background:linear-gradient(180deg,#10091e22,#10091e80),var(--access-cover,linear-gradient(135deg,#24153d,#101429)) center/cover no-repeat;
 border-radius:20px;
}
#gate.access-entry .gate-card {width:min(100%,420px);margin:0;padding:clamp(18px,4vw,32px);background:#161126ed;border-color:#aa84fc86;box-shadow:0 22px 72px #0008}
.access-entry .gate-card>h1,.access-entry .gate-card>p,.access-entry .gate-card>.eyebrow {text-align:center}
.access-entry .gate-card>h1 br{display:none}
.access-entry .gate-card>h1 br+span::before{content:" "}
.access-entry .gate-symbol{margin-inline:auto;overflow:hidden}
.access-entry .primary{background:#ffd878;color:#24152d}
.access-admin {margin-top:16px;color:#e1caef;font-size:.85rem}
.access-admin summary {cursor:pointer}
.access-links{display:flex;justify-content:center;flex-wrap:wrap;gap:8px 17px;margin-top:18px;font-size:.8rem}
.access-links a {color:#e6d3ff;text-underline-offset:3px}
.access-entry :focus-visible {outline:2px solid #ffdc81;outline-offset:4px}
