.radar-activity{margin:0 0 16px;border:1px solid #46376d;border-radius:14px;padding:12px 15px;background:#201833}
.radar-activity[hidden]{display:none}
.radar-activity h2{font-size:.8rem;letter-spacing:.08em;text-transform:uppercase;margin:0 0 8px;color:#d7befd}
.radar-activity ul{display:flex;flex-wrap:wrap;gap:6px 14px;list-style:none;margin:0;padding:0}
.radar-activity li{font-size:.8rem;color:#d8c9f0}
.radar-activity time{color:#c2afd8;margin-left:3px;white-space:nowrap}
