.radar-art-spirit{background-image:url("data:image/webp;base64,")}

:root{--pv-full-cover:url("data:image/webp;base64,");--pv-clean-logo:url("data:image/svg+xml;base64,")}
.shell .brandicon,.access-entry .gate-symbol{border-radius:23%;overflow:hidden}
.pv-clean-brand{background-image:var(--pv-clean-logo)!important;background-size:contain!important;background-position:center!important;background-repeat:no-repeat!important}
.pv-clean-brand img{visibility:hidden}
#gate.access-entry:not(.hidden){position:relative;isolation:isolate;background:#120d26;padding:clamp(20px,3vw,38px) 16px;min-height:calc(100svh - 80px)}
#gate.access-entry::before{content:"";position:absolute;inset:0;z-index:-1;border-radius:inherit;background:var(--access-cover,var(--pv-full-cover)) center / contain no-repeat}
#gate.access-entry .gate-card{padding:clamp(20px,3vw,28px);background:#171a2def;border-color:#7666b380}
#gate.access-entry .gate-card h1{font-size:clamp(27px,5vw,37px);text-transform:uppercase;font-weight:900;letter-spacing:-.035em}
#gate.access-entry .gate-card h1 .grad{color:#f6f2ff;background:none;-webkit-text-fill-color:currentColor}
#gate.access-entry .gate-symbol{width:58px;height:58px}
#gate.access-entry .gate-card>.eyebrow{display:none}
#gate.access-entry .gate-card .primary{border:0;background:#ffd568;color:#251a15}
.viewer-mode .main-content{background:linear-gradient(#101329f2,#101329f2),var(--pv-full-cover) center top / 100% auto no-repeat;border-radius:15px}
#feedRows.radar-grid{grid-template-columns:repeat(auto-fit,minmax(min(365px,100%),1fr));gap:13px}
.radar-card{padding:12px;border-radius:13px;border-color:#56467f;background:#171e39}
.radar-zone{color:#bdabff;font-size:10px;text-transform:uppercase;letter-spacing:.16em;font-weight:850;margin:0 0 8px}
.radar-title{grid-template-columns:56px minmax(0,1fr) auto;gap:9px;margin:0 0 12px}
.radar-title h2{font-size:clamp(13px,3vw,18px);font-weight:900;text-transform:uppercase}
.radar-title .radar-count{margin:4px 0 0;line-height:1.65}
.radar-thumb{height:56px;background:transparent}
.radar-art{width:56px;height:56px}
.radar-best{display:grid;text-align:right;justify-items:end;line-height:1.15}
.radar-best small{font-size:9px;letter-spacing:.15em;text-transform:uppercase}
.radar-best strong{color:#ffd363;font-size:clamp(15px,3.5vw,24px);font-variant-numeric:tabular-nums;margin-top:3px}
.radar-best span{font-size:10px;color:#cbd4f3;background:#242e50;border-radius:4px;padding:3px;margin-top:3px}
.radar-report{margin:5px 0;padding:8px;border:1px solid #3c4774;background:#21294a;border-radius:8px}
.radar-report-absent{border-color:#744755;background:#302039}
.radar-report .join-button:not(.join-disabled){border:0;background:#ffce58;color:#2a1b12;font-weight:900;padding:8px 11px}
.radar-value{display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;color:#e3e7ff;font-weight:800}
.radar-value strong{color:#ffd468}
.radar-report .radar-old{white-space:normal;text-align:right;max-width:120px}
@media(max-width:720px){
 #gate.access-entry:not(.hidden){align-items:start;padding-top:clamp(118px,34vw,205px)}
 #gate.access-entry::before{background-position:center top;background-size:100% auto}
 #feedRows.radar-grid{grid-template-columns:1fr;padding:9px}
 .radar-toolbar{padding:10px;gap:8px}
 .radar-toolbar label{flex:1;min-width:108px}
}

