.viewer-mode .workspace>.sidebar,.viewer-mode .radar-intro,.viewer-mode #refreshBtn,.viewer-mode .radar-results-label{display:none}
.viewer-mode .workspace{grid-template-columns:minmax(0,1fr)}
.viewer-mode .section-top{margin-bottom:10px}
.viewer-mode .section-actions{margin:0}
.radar-toolbar{align-items:center}
.radar-toolbar [role=group]{flex-wrap:wrap}
.radar-toolbar .radar-sort-row{width:100%;display:flex;flex-wrap:wrap;gap:4px;border-top:1px solid #3c355b;padding-top:8px}
.radar-sort-row button{border-color:transparent;background:transparent;color:#d8c9ef}
.radar-sort-row button[aria-pressed=true]{background:#30264e;color:#fff}
.radar-filter-menu{flex:none}
.radar-filter-menu[open]{width:100%}
.radar-filter-menu summary{cursor:pointer;display:inline-block;border:1px solid #665187;background:#201832;color:#fff;border-radius:8px;padding:8px 11px}
.radar-filter-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px;margin-top:8px}
.radar-filter-fields input,.radar-filter-fields select{width:100%;min-width:0}
.radar-toolbar .radar-random{border:0;background:#ffce58;color:#2a1b12;font-weight:900}
.radar-toolbar .radar-random[hidden]{display:none}

.radar-discord,.radar-logout{display:none}
.viewer-mode .radar-discord,.viewer-mode .radar-logout{display:inline-flex;align-items:center;color:#e6d6ff;background:#251c3b;border:1px solid #5c4a7d;padding:6px 9px;border-radius:8px;font:inherit;font-size:12px;text-decoration:none}
